import type {
  I18n_Config_DefaultLocale,
  I18n_Config_HasLocale_Locale,
  I18n_Config_HasLocale_TypeGuard,
  I18n_Config_Locales,
} from '../types/i18n/config.d.ts';

/**
 * Config - Default Locale.
 *
 * Keeps English available before consumers add translated dictionaries.
 * Acts as the destination for requests without a supported locale prefix.
 *
 * @since 0.0.0
 */
export const defaultLocale: I18n_Config_DefaultLocale = 'en';

/**
 * Config - Locales.
 *
 * Defines the locale routes generated by the application.
 * Consumers extend this list alongside their server-side dictionaries.
 *
 * @since 0.0.0
 */
export const locales: I18n_Config_Locales = ['en'];

/**
 * Config - Has Locale.
 *
 * Narrows an incoming route segment to a supported application locale.
 * Keeps route validation synchronized with the configured locale list.
 *
 * @param {I18n_Config_HasLocale_Locale} locale - Locale.
 *
 * @returns {I18n_Config_HasLocale_TypeGuard}
 *
 * @since 0.0.0
 */
export function hasLocale(locale: I18n_Config_HasLocale_Locale): locale is I18n_Config_HasLocale_TypeGuard {
  return locales.some((supportedLocale) => supportedLocale === locale);
}
